ver-status{font-size:8px;letter-spacing:1.1px;color:#c5bdae;margin-right:8px}.server-status i{display:inline-block;width:6px;height:6px;background:#a4a778;border-radius:50%;box-shadow:0 0 7px #c5d58b;margin-right:7px}.icon-button{width:30px;height:30px;border:1px solid rgba(218,182,119,.25);background:#181310aa;color:#c1b29a;cursor:pointer;font-size:16px}.icon-button:hover{border-color:var(--gold);color:var(--gold-bright)}.hero-panel{position:absolute;left:28px;top:96px;width:272px;padding:10px 12px 10px 10px;display:flex;gap:12px;align-items:center;background:linear-gradient(90deg,rgba(18,14,12,.91),rgba(18,14,12,.55));border:1px solid rgba(221,184,121,.25);border-left:2px solid #ba8f56;z-index:3;box-shadow:0 8px 24px #0005}.portrait{width:48px;height:48px;position:relative;flex:none;background:radial-gradient(circle at 50% 35%,#9a7350,#3b2b21 58%,#17110f);border:1px solid #9a7951;display:grid;place-items:center}.portrait-art{font-size:25px;color:#dfc491;text-shadow:0 2px 6px #000}.level-badge{position:absolute;bottom:-6px;right:-6px;background:#201812;border:1px solid var(--gold);font:10px var(--serif);color:var(--gold-bright);padding:2px 4px}.hero-info{flex:1;min-width:0}.hero-title{display:flex;flex-direction:column;gap:2px;margin-bottom:7px}.class-tag{font-size:7px;letter-spacing:1.8px;color:#bd9c6d}.hero-name{font:600 12px var(--serif);letter-spacing:1.2px;color:#f2e9dc}.meter-row{display:flex;align-items:center;gap:6px;margin-top:4px}.meter-icon{font-size:10px;color:#b5a27f;width:10px}.meter-icon.heart{color:#d86856}.meter{height:9px;position:relative;background:#332421;border:1px solid #60413b;flex:1;overflow:hidden}.meter-fill{height:100%;transition:width .3s}.health-fill{background:linear-gradient(90deg,#79392f,#c65b4a);width:100%}.xp-meter{height:6px;background:#29251d;border-color:#51442c}.xp-fill{background:linear-gradient(90deg,#99732c,#d5b661);width:76.5%}.meter>span{position:absolute;inset:0;text-align:center;font-size:7px;line-height:8px;color:#f5ea