-bar{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);height:72px;display:flex;align-items:center;gap:14px;padding:7px 14px;background:linear-gradient(180deg,rgba(29,23,19,.93),rgba(16,13,11,.96));border:1px solid rgba(207,174,122,.35);box-shadow:0 5px 25px #000a;z-index:4}.action-bar:before{content:'';position:absolute;top:-1px;left:22%;right:22%;height:1px;background:linear-gradient(90deg,transparent,#ddbb7d,transparent)}.resource{width:80px;text-align:center}.resource-label{font-size:7px;letter-spacing:1.4px;color:#9c8b70}.stamina-dots{display:flex;justify-content:center;gap:5px;margin-top:7px}.stamina-dots i{width:8px;height:8px;border:1px solid #cda86d;transform:rotate(45deg);background:#a78040;box-shadow:0 0 6px #c08a40}.abilities{display:flex;gap:7px}.ability{width:56px;height:56px;position:relative;cursor:pointer;background:linear-gradient(145deg,#322820,#171310 72%);border:1px solid #796144;box-shadow:inset 0 0 8px #0007;transition:transform .12s,border-color .12s}.ability:hover{border-color:#ebcb91;transform:translateY(-2px)}.ability:active{transform:scale(.94)}.ability-key{position:absolute;left:4px;top:3px;font-size:8px;color:#dac698}.ability-glyph{position:absolute;inset:0;display:grid;place-items:center;font-size:24px;color:#e3c88e;text-shadow:0 0 12px #a16a33}.ability-glyph.cleave{color:#d77d55}.ability-glyph.guard{color:#b6b995}.ability-glyph.potion{color:#be7060}.ability-name{position:absolute;bottom:-14px;left:50%;transform:translateX(-50%);font-size:6px;letter-spacing:.6px;color:#b8aa94;white-space:nowrap}.ability-name b{color:#e6c982;font-weight:500}.cooldown{position:absolute;inset:0;background:rgba(11,10,9,.64);transform:scaleY(0);transform-origin:bottom;pointer-events:none}.ability.cooling .cooldown{transform:scaleY(1);transition:transform linear}.bag-area{height:49px;border-left:1px solid rgba(211,179,128,.2);padding-left:12px;margin-left:1px}.bag-button{position:relative;width:41px;height:49px;background:transparent;border:0