import * as THREE from 'three';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x17130f);
scene.fog = new THREE.FogExp2(0x17130f, 0.027);
const camera = new THREE.PerspectiveCamera(48, innerWidth / innerHeight, 0.1, 100);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

scene.add(new THREE.HemisphereLight(0xb4a38d, 0x251712, 1.35));
const moon = new THREE.DirectionalLight(0xc8bfa9, 1.4);
moon.position.set(-5, 12, 4); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -17; moon.shadow.camera.right = 17; moon.shadow.camera.top = 17; moon.shadow.camera.bottom = -17;
scene.add(moon);
const emberLight = new THREE.PointLight(0xff762e, 22, 12, 1.8); emberLight.position.set(0, 3.2, -9); scene.add(emberLight);

const mats = {
  floor: new THREE.MeshStandardMaterial({ color: 0x494038, roughness: 0.96 }),
  stone: new THREE.MeshStandardMaterial({ color: 0x51483e, roughness: 0.92 }),
  darkStone: new THREE.MeshStandardMaterial({ color: 0x302a25, roughness: 1 }),
  trim: new THREE.MeshStandardMaterial({ color: 0x806848, roughness: 0.8, metalness: 0.17 }),
  gold: new THREE.MeshStandardMaterial({ color: 0xd3a850, roughness: 0.4, metalness: 0.55, emissive: 0x43250a }),
  hero: new THREE.MeshStandardMaterial({ color: 0x4d6370, roughness: 0.68, metalness: 0.3 }),
  leather: new THREE.MeshStandardMaterial({ color: 0x493022, roughness: 0.9 }),
  skin: new THREE.MeshStandardMaterial({ color: 0xd2a77e, roughness: 0.85 }),
  blade: new THREE.MeshStandardMaterial({ color: 0xd3d5c9, roughness: 0.24, metalness: 0.8 }),
  goblin: new THREE.MeshStandardMaterial({ color: 0x68764d, roughness: 0.8 }),
  cloth: new THREE.MeshStandardMaterial({ color: 0x5c3025, roughness: 0.9 }),
  flame: new THREE.MeshStandardMaterial({ color: 0xff9a42, emissive: 0xf45c16, emissiveIntensity: 2 }),
  crystal: new THREE.MeshStandardMaterial({ color: 0x9b4838, emissive: 0x9d2511, emissiveIntensity: 1.2, roughness: .3 })
};

function box(parent, name, size, pos, material, rot = [0, 0, 0]) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material);
  mesh.name = name; mesh.position.set(...pos); mesh.rotation.set(...rot); mesh.castShadow = true; mesh.receiveShadow = true;
  parent.add(mesh); return mesh;
}
function cylinder(parent, radiusTop, radiusBottom, height, pos, material, segments = 8) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
  mesh.position.set(...pos); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function sphere(parent, radius, pos, material, scale = [1,1,1], segments = 10) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, segments, Math.max(6, segments - 2)), material);
  mesh.position.set(...pos); mesh.scale.set(...scale); mesh.castShadow = true; parent.add(mesh); return mesh;
}

// A fallen abbey crypt: hand-laid flagstones, ribs, pillars, and a sealed reliquary door.
const floor = new THREE.Mesh(new THREE.PlaneGeometry(34, 34), mats.darkStone);
floor.rotation.x = -Math.PI / 2; floor.position.y = -0.12; floor.receiveShadow = true; scene.add(floor);
const tileMats = [mats.floor, mats.stone, new THREE.MeshStandardMaterial({color:0x403830, roughness:.98}), new THREE.MeshStandardMaterial({color:0x574b3f,roughness:.95})];
