  box(model,'helm brow',[.36,.1,.25],[0,1.72,.05],mats.gold);
  box(model,'face shadow',[.22,.07,.08],[0,1.68,.17],mats.darkStone);
  sphere(model,.08,[-.17,1.03,0],mats.gold,[.55,1.35,.8],8);
  const armL=cylinder(model,.105,.13,.53,[-.37,1.15,0],mats.leather,7); armL.rotation.z=-.22;
  const armR=cylinder(model,.105,.13,.53,[.37,1.15,0],mats.leather,7); armR.rotation.z=.22;
  const legL=cylinder(model,.13,.16,.52,[-.14,.42,0],mats.darkStone,7);
  const legR=cylinder(model,.13,.16,.52,[.14,.42,0],mats.darkStone,7);
  box(model,'belt',[.53,.1,.35],[0,.78,0],mats.gold);
  // sword held at a readable angle
  const sword=new THREE.Group(); sword.position.set(.49,1.18,.08); sword.rotation.z=-.32; sword.rotation.x=-.16; model.add(sword);
  box(sword,'longsword blade',[.1,.92,.045],[0,.55,0],mats.blade,[0,0,-.045]);
