function makeBoss(){
  const root=new THREE.Group();root.position.set(0,0,-10);scene.add(root);
  const model=new THREE.Group();root.add(model);
  // compact, low-poly ember wyrm with a horned head, wings, and a curling tail
  const body=sphere(model,1,[0,1.45,0],enemyMats.wyrm,[1.2,.82,1.6],12);
  sphere(model,.68,[0,1.8,-1.03],enemyMats.scale,[1.05,.82,1.03],10);
  const snout=sphere(model,.43,[0,1.58,-1.75],enemyMats.wyrm,[.85,.56,1.08],9);
  for(const s of [-1,1]){
    const horn=new THREE.Mesh(new THREE.ConeGeometry(.18,.75,6),mats.trim);horn.position.set(s*.43,2.45,-1.1);horn.rotation.z=-s*.45;model.add(horn);
    sphere(model,.075,[s*.3,1.95,-1.75],mats.flame,[1,.8,.6],7);
    const wing=new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape().setFromPoints([new THREE.Vector2(0,0),new THREE.Vector2(s*2.15,.8),new THREE.Vector2(s*1.65,-1.2),new THREE.Vector2(s*.3,-.55)])),new THREE.MeshStandardMaterial({color:0x592820,side:THREE.DoubleSide,roughness:.8}));
    wing.position.set(s*.62,1.7,.1);wing.rotation.y=s*.15;wing.rotation.x=-.1;model.add(wing);
    for(let i=0;i<5;i++){const spike=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,5),enemyMats.scale);spike.position.set(s*(.55+i*.23),2.1,.65-i*.45);spike.rotation.z=-s*.4;model.add(spike)}
  }
  const tail=sphere(model,.4,[0,1.18,1.85],enemyMats.wyrm,[.62,.65,1.9],9);tail.rotation.x=.2;
  for(let i=0;i<3;i++){const fire=sphere(model,.17,[0,.24+i*.1,-1.8-i*.15],mats.flame,[1.2,1.5,1],7);fire.userData.phase=i}
  const boss={root,model,name:'Vaelgor, the Ember Wyrm',type:'ANCIENT WYRMLING',level:6,hp:310,maxHp:310,damage:13,speed:.72,alive:true,attackTimer:2,phase:0,kind:'boss'};
  enemies.push(boss);bossSpawned=true;
  announce('THE EMBER WYRM AWAKENS'); log('A vast shape stirs behind the seal.');
  document.querySelector('#boss-objective').classList.remove('muted');
  if(kills>=3) document.querySelector('#objective').classList.add('muted');
