function rollD20(bonus){const roll=1+Math.floor(Math.random()*20);return {roll,total:roll+bonus,crit:roll===20,miss:roll===1}}
function closeEnough(enemy,range=3.15){return player.position.distanceTo(enemy.root.position)<=range+(enemy.kind==='boss'?.65:0)}
function chooseTarget(){const alive=enemies.filter(e=>e.alive);if(!alive.length)return null;return alive.reduce((a,b)=>player.position.distanceTo(a.root.position)<player.position.distanceTo(b.root.position)?a:b)}
function hitEnemy(enemy,damage,ability='Steel Strike'){
  if(!enemy.alive)return;
  enemy.hp=Math.max(0,enemy.hp-damage);floatingText(`-${damage}`,enemy.root.position,enemy.kind==='boss'?'enemy-hit':'');
  if(activeTarget===enemy){document.querySelector('#target-health-fill').style.width=`${enemy.hp/enemy.maxHp*100}%`}
  enemy.root.userData.hitFlash=.14;
  log(`${ability} deals <b>${damage}</b> damage to ${enemy.name}.`);
  if(enemy.hp<=0)killEnemy(enemy);
}
function attack(enemy=activeTarget,kind='strike'){
  if(!gameStarted||gameOver)return;
  enemy ||= chooseTarget();if(!enemy){announce('NO FOE IN SIGHT');return}
  if(!enemy.alive)return;
  if(!closeEnough(enemy,kind==='cleave'?3.8:3.1)){
    setTarget(enemy);announce('MOVE CLOSER TO STRIKE');return;
  }
  setTarget(enemy);attackAnim=.35;player.userData.sword.rotation.x=-.8;playTone(kind==='cleave'?115:180,.16,'sawtooth');
  const roll=rollD20(kind==='cleave'?7:6);const defense=enemy.kind==='boss'?14:12;
  if(roll.miss){log(`D20: ${roll.roll} + 6 = ${roll.total} — a miss.`);floatingText('MISS',enemy.root.position,'enemy-hit');return}
  if(roll.total<defense){log(`D20: ${roll.roll} + 6 = ${roll.total} — deflected.`);return}
  const damage=(kind==='cleave'?24:15)+Math.floor(Math.random()*10)+(roll.crit?18:0);
  if(roll.crit){log(`<b>Natural 20!</b> A critical hit!`);announce('CRITICAL STRIKE!');playTone(420,.25,'triangle')}
  if(kind==='cleave'){
    hitEnemy(enemy,damage,'Cleave');
    for(const other of enemies){if(other!==enemy&&other.alive&&player.position.distanceTo(other.root.position)<4)hitEnemy(other,Math.floor(damage*.65),'Cleave')}
    spendStamina(1);
  }else hitEnemy(enemy,damage,roll.crit?'Critical strike':'Steel Strike');
}
function spendStamina(amount){stamina=Math.max(0,stamina-amount);updateStamina();setTimeout(()=>{stamina=Math.min(5,stamina+amount);updateStamina()},1800)}
function updateStamina(){document.querySelectorAll('#stamina-dots i').forEach((el,i)=>el.style.opacity=i<stamina?'1':'.22')}
function killEnemy(enemy){
  enemy.alive=false;scene.remove(enemy.root);setTarget(activeTarget===enemy?null:activeTarget);playTone(90,.32,'triangle');
  if(enemy.kind==='boss'){
    log('Vaelgor collapses into a heap of smoldering scales.');
    announce('THE WYRM IS SLAIN');xp+=850;document.querySelector('#objective').classList.add('muted');document.querySelector('#boss-objective').querySelector('b').textContent='DONE';document.querySelector('#boss-objective').classList.add('done');
    document.querySelector('.quest-reward')?.remove();const banner=document.querySelector('#objective-banner');banner.querySelector('small').textContent='QUEST COMPLETE';banner.querySelector('strong').textContent='The reliquary is yours.';banner.classList.add('show');setTimeout(()=>banner.classList.remove('show'),4500);
    log('Quest complete: The Sunken Reliquary. <b>+850 XP</b>');return;
  }
  kills++;xp+=150;document.querySelector('#kill-count').textContent=`${kills} / 3`;
  log(`${enemy.name} falls. <b>+150 XP</b>`);document.querySelector('#xp-fill').style.width=`${Math.min(100,xp/3200*100)}%`;document.querySelector('#xp-text').textContent=`${xp.toLocaleString()} / 3,200 XP`;
  if(kills===1){const banner=document.querySelector('#objective-banner');banner.querySelector('small').textContent='GUARDIAN DEFEATED';banner.querySelector('strong').textContent='The crypt grows quiet… too quiet.';banner.classList.add('show');setTimeout(()=>banner.classList.remove('show'),2600)}
  if(kills>=3&&!bossSpawned){document.querySelector('#objective').classList.add('muted');setTimeout(makeBoss,800)}
}
function heal(){if(!gameStarted||gameOver)return;if(potions<=0){announce('NO DRAUGHTS LEFT');return}if(hp>=maxHp){announce('VIGOR IS ALREADY FULL');return}potions--;const amount=Math.min(45,maxHp-hp);hp+=amount;document.querySelector('#potion-count').textContent=`×${potions}`;document.querySelector('#health-fill').style.width=`${hp/maxHp*100}%`;document.querySelector('#health-text').textContent=`${hp} / ${maxHp}`;floatingText(`+${amount}`,player.position,'heal');log(`Healing draught restores <b>${amount}</b> vigor.`);playTone(540,.25,'sine')}
function ironGuard(){if(!gameStarted||gameOver)return;guarding=4;guardTimer=4;announce('IRON GUARD');log('You brace behind your shield. Incoming damage reduced.');document.querySelector('#ability-guard').classList.add('cooling');setTimeout(()=>document.querySelector('#ability-guard').classList.remove('cooling'),4500)}
function takeDamage(amount,enemy){const actual=Math.max(1,Math.floor(amount*(guarding>0?.48:1)));hp=Math.max(0,hp-actual);document.querySelector('#health-fill').style.width=`${hp/maxHp*100}%`;document.querySelector('#health-text').textContent=`${hp} / ${maxHp}`;floatingText(`-${actual}`,player.position,'enemy-hit');log(`${enemy.name} hits you for <b>${actual}</b> damage.`);playTone(72,.16,'square',.025);if(hp<=0){gameOver=true;document.querySelector('#death-screen').classList.remove('hidden')}}

function beginGame(){gameStarted=true;document.querySelector('#start-screen').classList.add('hidden');const banner=document.querySelector('#objective-banner');banner.classList.add('show');setTimeout(()=>banner.classList.remove('show'),3100);log('You descend into the Ashen Crypt.')}
document.querySelector('#begin-button').addEventListener('click',beginGame);
document.querySelector('#retry-button').addEventListener('click',()=>location.reload());
document.querySelector('#ability-attack').addEventListener('click',()=>attack());
document.querySelector('#ability-cleave').addEventListener('click',()=>attack(activeTarget,'cleave'));
document.querySelector('#ability-guard').addEventListener('click',ironGuard);
document.querySelector('#ability-potion').addEventListener('click',heal);
document.querySelector('#inventory-button').addEventListener('click',()=>document.querySelector('#inventory-modal').classList.add('open'));
document.querySelector('#close-inventory').addEventListener('click',()=>document.querySelector('#inventory-modal').classList.remove('open'));
document.querySelector('#quest-toggle').addEventListener('click',()=>{const q=document.querySelector('.quest-card');q.classList.toggle('collapsed');document.querySelector('#quest-toggle').textContent=q.classList.contains('collapsed')?'+':'−'});
document.querySelector('#fullscreen').addEventListener('click',()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()});
document.querySelector('#sound-toggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.classList.toggle('active',soundOn);e.currentTarget.style.color=soundOn?'#f2d59a':'';if(soundOn)playTone(550,.08)});
window.addEventListener('keydown',e=>{
  if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();
  if(e.code==='Escape'){document.querySelector('#inventory-modal').classList.remove('open');return}
  if(!gameStarted){if(e.code==='Enter')beginGame();return}
  if(e.repeat)return;
  keys.add(e.code);
  if(e.code==='Space'||e.code==='KeyF')attack();
  if(e.code==='Digit1')attack(activeTarget,'cleave');
  if(e.code==='Digit2')ironGuard();
  if(e.code==='Digit3')heal();
  if(e.code==='KeyE'&&activeTarget&&closeEnough(activeTarget))attack(activeTarget);
});
window.addEventListener('keyup',e=>keys.delete(e.code));
canvas.addEventListener('pointerdown',e=>{
  if(!gameStarted||e.button!==0)return;
  pointer.x=(e.clientX/innerWidth)*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);
  const meshes=[];for(const enemy of enemies)if(enemy.alive)enemy.root.traverse(o=>{if(o.isMesh){o.userData.enemy=enemy;meshes.push(o)}});
  const hit=raycaster.intersectObjects(meshes,false)[0];if(hit){setTarget(hit.object.userData.enemy);if(closeEnough(activeTarget))attack(activeTarget)}else if(activeTarget&&closeEnough(activeTarget))attack(activeTarget);
});
for(const btn of document.querySelectorAll('[data-move]')){
  const mapping={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'},code=mapping[btn.dataset.move];
  btn.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(code)});['pointerup','pointerleave','pointercancel'].forEach(ev=>btn.addEventListener(ev,()=>keys.delete(code)));
}
document.querySelector('#touch-attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});

const targetRing=new THREE.Mesh(new THREE.TorusGeometry(.78,.035,6,40),new THREE.MeshBasicMaterial({color:0xe6b962,transparent:true,opacity:.88}));
targetRing.rotation.x=-Math.PI/2;targetRing.position.y=.075;targetRing.visible=false;scene.add(targetRing);
let swingLock=0;
const originalAttack=attack;
// A short deliberate recovery keeps attacks readable without slowing the brawl.
function performAttack(enemy,kind){if(swingLock>0){return} swingLock=kind==='cleave'?.85:.58;originalAttack(enemy,kind)}
// Route all input through the recovery-gated combat action.
document.querySelector('#ability-attack').onclick=()=>performAttack(activeTarget,'strike');
document.querySelector('#ability-cleave').onclick=()=>performAttack(activeTarget,'cleave');
document.querySelector('#touch-attack').onpointerdown=e=>{e.preventDefault();performAttack(activeTarget,'strike')};
// Replace key combat bindings installed above with gated versions.
window.addEventListener('keydown',e=>{if(!gameStarted||gameOver||e.repeat)return;if(e.code==='Space'||e.code==='KeyF')performAttack(activeTarget,'strike');if(e.code==='Digit1')performAttack(activeTarget,'cleave');if(e.code==='KeyE'&&activeTarget&&closeEnough(activeTarget))performAttack(activeTarget,'strike')});
canvas.addEventListener('pointerdown',e=>{
  if(!gameStarted||e.button!==0)return;
  pointer.x=(e.clientX/innerWidth)*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);
  const meshes=[];for(const enemy of enemies)if(enemy.alive)enemy.root.traverse(o=>{if(o.isMesh){o.userData.enemy=o.userData.enemy||enemy;meshes.push(o)}});
  const hit=raycaster.intersectObjects(meshes,false)[0];if(hit){setTarget(hit.object.userData.enemy);if(closeEnough(activeTarget))performAttack(activeTarget,'strike')}
});

function update(dt,time){
  if(attackAnim>0){attackAnim=Math.max(0,attackAnim-dt);const swing=Math.sin((.35-attackAnim)/.35*Math.PI);player.userData.sword.rotation.x=-.16-swing*1.35;player.userData.armR.rotation.z=.22-swing*.8}else{player.userData.sword.rotation.x=-.16;player.userData.armR.rotation.z=.22}
  if(swingLock>0)swingLock=Math.max(0,swingLock-dt);
  if(guardTimer>0){guardTimer=Math.max(0,guardTimer-dt);guarding=guardTimer>0?1:0}
  for(const b of braziers){const f=Math.sin(time*8+b.phase);b.flame.scale.y=1.5+f*.23;b.flame.position.y=1.06+f*.035;b.light.intensity=14+f*3}
  sealCore.material.emissiveIntensity=.9+Math.sin(time*2.7)*.4;seal.rotation.z=time*.18;
  const moving=gameStarted&&!gameOver&&document.querySelector('#inventory-modal').classList.contains('open')===false;
  let dx=0,dz=0;
  if(moving){if(keys.has('KeyW')||keys.has('ArrowUp'))dz-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))dz+=1;if(keys.has('KeyA')||keys.has('ArrowLeft'))dx-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))dx+=1}
  const isWalking=dx!==0||dz!==0;
  if(isWalking){const len=Math.hypot(dx,dz);dx/=len;dz/=len;const speed=4.4;player.position.x=THREE.MathUtils.clamp(player.position.x+dx*speed*dt,-8.25,8.25);player.position.z=THREE.MathUtils.clamp(player.position.z+dz*speed*dt,-14.5,14.5);player.rotation.y=Math.atan2(dx,dz)+Math.PI;const gait=Math.sin(time*11);player.userData.legL.rotation.x=gait*.45;player.userData.legR.rotation.x=-gait*.45;player.userData.model.position.y=Math.abs(gait)*.045}else{player.userData.legL.rotation.x=THREE.MathUtils.damp(player.userData.legL.rotation.x,0,9,dt);player.userData.legR.rotation.x=THREE.MathUtils.damp(player.userData.legR.rotation.x,0,9,dt);player.userData.model.position.y=THREE.MathUtils.damp(player.userData.model.position.y,0,8,dt)}
  if(activeTarget?.alive){targetRing.visible=true;targetRing.position.set(activeTarget.root.position.x,.08,activeTarget.root.position.z);targetRing.rotation.z=time*.55;if(!isWalking){const d=activeTarget.root.position.clone().sub(player.position);player.rotation.y=Math.atan2(d.x,d.z)+Math.PI}}
  else targetRing.visible=false;
  for(const enemy of enemies){
    if(!enemy.alive)continue;
    enemy.phase+=dt*2.4;enemy.model.position.y=Math.sin(enemy.phase)*.025;
    const delta=player.position.clone().sub(enemy.root.position);delta.y=0;const dist=delta.length();
    if(dist>.01){enemy.root.rotation.y=Math.atan2(delta.x,delta.z)+Math.PI}
    const reach=enemy.kind==='boss'?3.3:2.05;
    if(dist>reach){const speed=enemy.speed*(enemy.kind==='boss'?1:1);enemy.root.position.x+=delta.x/dist*speed*dt;enemy.root.position.z+=delta.z/dist*speed*dt}
    enemy.attackTimer-=dt;
    if(dist<=reach&&enemy.attackTimer<=0){enemy.attackTimer=enemy.kind==='boss'?2.15:1.75+Math.random()*.55;enemy.model.rotation.x=-.12;setTimeout(()=>{if(enemy.model)enemy.model.rotation.x=0},170);takeDamage(enemy.damage,enemy);if(gameOver)break}
    if(enemy.kind==='boss'){enemy.model.rotation.z=Math.sin(time*1.4)*.025;const fire=enemy.model.children.filter(o=>o.material===mats.flame);for(const f of fire){f.scale.y=1.2+Math.sin(time*11+(f.userData.phase||0))*0.3}}
  }
  // soft third-person follow; camera aim floats just ahead of the hero
  const desired=new THREE.Vector3(player.position.x,player.position.y+7.7,player.position.z+10.2);
  camera.position.lerp(desired,1-Math.exp(-4.2*dt));camera.lookAt(player.position.x,player.position.y+1.25,player.position.z-1.0);
  emberLight.intensity=20+Math.sin(time*4)*2;
}
function render(){requestAnimationFrame(render);const dt=Math.min(clock.getDelta(),.045),time=clock.elapsedTime;update(dt,time);renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
updateStamina();render();

